3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Мины</title>
7	<style>
8	  :root { color-scheme: light dark; --accent: #2563eb; --win: #16a34a; --lose: #dc2626; --muted: #6b7280; }
9	  * { box-sizing: border-box; }
10	  body { margin: 0; font-family: system-ui, sans-serif; background: Canvas; color: CanvasText; }
11	  main { max-width: 420px; margin: 0 auto; padding: 24px 16px; display: grid; gap: 16px; }
12	  h1 { margin: 0; font-size: 24px; }
13	  .row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
14	  .label { color: var(--muted); font-size: 14px; }
15	  .balance { font-size: 20px; font-weight: 600; }
16	  input { font: inherit; padding: 8px; width: 100px; }
17	  button { font: inherit; padding: 10px 16px; border-radius: 8px; border: 1px solid var(--muted); background: transparent; color: inherit; cursor: pointer; }
18	  button:disabled { opacity: .5; cursor: default; }
19	  #play { background: var(--accent); color: #fff; border-color: var(--accent); flex: 1; font-weight: 600; }
20	  #cashout { border-color: var(--win); color: var(--win); flex: 1; font-weight: 600; }
21	  .grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px; }
22	  .cell { aspect-ratio: 1; padding: 0; font-size: 22px; font-weight: 700; }
23	  .cell[data-cell-state="safe"] { background: var(--win); border-color: var(--win); color: #fff; opacity: 1; }
24	  .cell[data-cell-state="mine"] { background: var(--lose); border-color: var(--lose); color: #fff; opacity: 1; }
25	  .cell.hit { outline: 3px solid CanvasText; }
26	  .stats { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 8px; text-align: center; }
27	  .stats b { display: block; font-size: 18px; }
28	  .result { text-align: center; min-height: 1.5em; font-weight: 600; }
29	  [data-state="won"] .result { color: var(--win); }
30	  [data-state="lost"] .result { color: var(--lose); }
31	  .error { color: var(--lose); min-height: 1.2em; }
32	</style>
33	</head>
34	<body>
35	<main data-testid="game" data-state="idle">
36	  <h1>Мины</h1>
37	  <div class="row"><span class="label">Баланс:</span> <span class="balance" data-testid="balance">—</span></div>
38	
39	  <div class="row">
40	    <label class="label" for="bet">Ставка</label>
41	    <input id="bet" data-testid="bet-input" type="number" step="0.01" min="1" max="10" value="1">
42	    <span class="label" id="limits"></span>
43	  </div>
44	
45	  <div class="row">
46	    <button type="button" id="play" data-testid="play">Новая игра</button>
47	    <button type="button" id="cashout" data-testid="cashout" disabled>Забрать</button>
48	  </div>
49	
50	  <div class="stats">
51	    <div><span class="label">Множитель</span><b data-testid="multiplier">—</b></div>
52	    <div><span class="label">Следующий</span><b data-testid="next-multiplier">—</b></div>
53	    <div><span class="label">Мин на поле</span><b id="mine-count">3</b></div>
54	  </div>
55	
56	  <div class="grid" id="grid" role="grid" aria-label="Поле 5 × 5"></div>
57	
58	  <div class="result" id="result">Выплата: <span data-testid="payout">—</span></div>
59	  <div class="error" data-testid="error" role="alert"></div>
60	</main>
61	<script src="/sdk.js"></script>
62	<script>
63	(function () {
64	  'use strict';
65	
66	  var CELLS = 25;
67	  var ERROR_TEXT = {
68	    BET_OUT_OF_LIMITS: 'Ставка вне лимитов',
69	    INSUFFICIENT_FUNDS: 'Недостаточно средств',
70	    INVALID_PARAMS: 'Неверные параметры',
71	    INVALID_ACTION: 'Недопустимый ход',
72	    ROUND_ALREADY_OPEN: 'Раунд уже открыт',
73	    ROUND_CLOSED: 'Раунд уже завершён',
74	    NETWORK_ERROR: 'Нет связи с сервером',
75	  };
76	  var started = false;
77	
78	  function init() {
79	    if (started) return;
80	    started = true;
81	
82	    var sdk = window.PlatformSDK;
83	    var q = function (id) { return document.querySelector('[data-testid="' + id + '"]'); };
84	    var root = q('game');
85	    var balanceEl = q('balance');
86	    var betInput = q('bet-input');
87	    var playBtn = q('play');
88	    var cashoutBtn = q('cashout');
89	    var multEl = q('multiplier');
90	    var nextEl = q('next-multiplier');
91	    var payoutEl = q('payout');
92	    var errorEl = q('error');
93	    var resultEl = document.getElementById('result');
94	    var limitsEl = document.getElementById('limits');
95	    var mineCountEl = document.getElementById('mine-count');
96	    var grid = document.getElementById('grid');
97	
98	    var cells = [];
99	    for (var i = 0; i < CELLS; i++) {
100	      var b = document.createElement('button');
101	      b.type = 'button';
102	      b.className = 'cell';
103	      b.setAttribute('data-testid', 'cell-' + i);
104	      b.setAttribute('data-cell', String(i));
105	      b.setAttribute('data-cell-state', 'hidden');
106	      b.setAttribute('aria-label', 'Клетка ' + (i + 1));
107	      grid.appendChild(b);
108	      cells.push(b);
109	    }
110	
111	    // Текущий вид раунда: null — раунда нет.
112	    var view = null;
113	    var phase = 'idle';
114	    var busy = false;
115	
116	    function money(n) { return Number(n).toFixed(2); }
117	    function setBalance(b) { if (typeof b === 'number') balanceEl.textContent = money(b); }
118	
119	    function showError(e) {
120	      var code = (e && e.code) || 'INTERNAL_ERROR';
121	      var text = ERROR_TEXT[code] || (e && e.message) || 'Ошибка';
122	      errorEl.textContent = code + ': ' + text;
123	    }
124	
125	    function render() {
126	      root.setAttribute('data-state', phase);
