136	        c.classList.toggle('hit', idx === hit);
137	        c.disabled = busy || phase !== 'playing' || st !== 'hidden';
138	      });
139	      playBtn.disabled = busy || phase === 'playing';
140	      cashoutBtn.disabled = busy || phase !== 'playing' || revealed.length < 1;
141	      betInput.disabled = busy || phase === 'playing';
142	      multEl.textContent = view ? '×' + view.multiplier : '—';
143	      nextEl.textContent = view && typeof view.nextMultiplier === 'number' ? '×' + view.nextMultiplier : '—';
144	      if (view && typeof view.mineCount === 'number') mineCountEl.textContent = String(view.mineCount);
