147	    function applyRound(round) {
148	      if (!round) return;
149	      setBalance(round.balance);
150	      view = round.view || null;
151	      if (round.status === 'open') {
152	        phase = 'playing';
153	        payoutEl.textContent = '—';
154	      } else if (view) {
155	        phase = view.outcome === 'mine' ? 'lost' : 'won';
156	        payoutEl.textContent = money(round.payout || 0);
