12	/** Ждёт выполнения условия, прокручивая очередь задач. */
13	async function waitFor(cond: () => boolean, what: string, timeoutMs = 3000): Promise<void> {
14	  const started = Date.now();
15	  for (;;) {
16	    let ok = false;
17	    try {
18	      ok = cond();
19	    } catch {
20	      ok = false;
21	    }
22	    if (ok) return;
23	    if (Date.now() - started > timeoutMs) throw new Error(`не дождались: ${what}`);
24	    await new Promise((r) => setTimeout(r, 5));
25	  }
26	}
