30	 * Подменённый SDK отвечает разрешённым промисом, поэтому всё, что интерфейс делает «сразу по ответу», успевает здесь.
31	 */
32	async function flushMicrotasks(turns = 50): Promise<void> {
33	  for (let i = 0; i < turns; i++) await Promise.resolve();
34	}
