58	// Слушатели, которые страница повесила на document/window: снимаются перед повторной «загрузкой»,
59	// чтобы скрипт прошлой загрузки не реагировал на события новой.
60	const tracked: Array<{ target: EventTarget; type: string; fn: any; opts: any }> = [];
61	let patched = false;
62	function trackListeners(): void {
63	  if (patched) return;
64	  patched = true;
65	  const g = globalThis as any;
66	  for (const target of [g.document, g.window] as EventTarget[]) {
67	    const orig = target.addEventListener.bind(target);
68	    (target as any).addEventListener = (type: string, fn: any, opts?: any) => {
69	      tracked.push({ target, type, fn, opts });
70	      return orig(type, fn, opts);
71	    };
72	  }
73	}
74	function dropListeners(): void {
75	  for (const l of tracked.splice(0)) l.target.removeEventListener(l.type, l.fn, l.opts);
76	}
