78	/** «Открывает» страницу: разметка без <script>, затем подмена SDK, затем инлайновые скрипты. */
79	function loadPage(sdk: unknown): void {
80	  trackListeners();
81	  dropListeners();
82	  const html = readFileSync(HTML_PATH, 'utf8');
83	  const scripts: string[] = [];
84	  const stripped = html.replace(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi, (_m, attrs: string, code: string) => {
85	    if (!/\bsrc\s*=/.test(attrs) && code.trim()) scripts.push(code);
86	    return '';
87	  });
88	  const doc = new DOMParser().parseFromString(stripped, 'text/html');
89	  for (const a of Array.from(doc.documentElement.attributes)) document.documentElement.setAttribute(a.name, a.value);
90	  for (const a of Array.from(doc.body.attributes)) document.body.setAttribute(a.name, a.value);
91	  document.head.innerHTML = doc.head.innerHTML;
92	  document.body.innerHTML = doc.body.innerHTML;
93	
94	  const g = globalThis as any;
95	  g.window.PlatformSDK = sdk;
96	  g.PlatformSDK = sdk;
97	  const indirectEval: (code: string) => unknown = g.eval;
98	  for (const code of scripts) indirectEval(code);
99	  document.dispatchEvent(new g.Event('DOMContentLoaded'));
100	  g.window.dispatchEvent(new g.Event('load'));
101	}
