110	function pageStyles(): string {
111	  const html = readFileSync(HTML_PATH, 'utf8');
112	  const parts: string[] = [];
113	  for (const m of html.matchAll(/<style\b[^>]*>([\s\S]*?)<\/style>/gi)) parts.push(m[1] ?? '');
114	  for (const m of html.matchAll(/\sstyle\s*=\s*"([^"]*)"/gi)) parts.push(m[1] ?? '');
