119	/** Время CSS в миллисекундах. */
120	const toMs = (num: string, unit: string): number => (unit.toLowerCase() === 's' ? Number(num) * 1000 : Number(num));
121	
122	/** Все длительности animation/transition (лонгхенды целиком, у шортхендов — первое время в каждом элементе списка). */
123	function durationsMs(rawCss: string): number[] {
124	  // Подставляем значения CSS-переменных (--flip: 250ms → var(--flip)), чтобы длительность через var() тоже проверялась.
125	  const vars = new Map<string, string>();
126	  for (const m of rawCss.matchAll(/(--[\w-]+)\s*:\s*([^;}]+)/g)) vars.set(m[1]!, m[2]!.trim());
127	  const css = rawCss.replace(/var\(\s*(--[\w-]+)\s*(?:,([^)]*))?\)/g, (_m, name: string, fallback?: string) =>
128	    vars.get(name) ?? (fallback ?? '').trim(),
129	  );
130	  const out: number[] = [];
131	  const re = /(?:^|[;{\s])(animation|transition)(-duration)?\s*:\s*([^;}]+)/gi;
132	  for (const m of css.matchAll(re)) {
133	    const longhand = Boolean(m[2]);
134	    for (const item of (m[3] ?? '').split(',')) {
135	      const times = [...item.matchAll(/(-?\d*\.?\d+)(ms|s)\b/gi)].map((t) => toMs(t[1]!, t[2]!));
136	      if (times.length === 0) continue;
137	      if (longhand) out.push(...times);
138	      else out.push(times[0]!);
139	    }
140	  }
141	  return out;
142	}
