13	/** rng, который отдаёт заданные числа и бросает, когда они кончились; считает вызовы. */
14	function countingRng(values: number[]) {
15	  let calls = 0;
16	  const rng = {
17	    next(): number {
18	      calls += 1;
19	      if (calls > values.length) throw new Error('rng: лишний вызов');
20	      return values[calls - 1] as number;
21	    },
22	  };
23	  return { rng, calls: () => calls };
24	}
