26	function gameErrorCode(fn: () => unknown): string {
27	  try {
28	    const v = fn();
29	    throw new Error(`ожидалась GameError, а вызов вернул ${JSON.stringify(v)}`);
30	  } catch (e: any) {
31	    expect(e).toBeInstanceOf(GameError);
32	    return e.code;
33	  }
34	}
