export function multiplier(k: number, mineCount: number = DEFAULT_MINES): number {
  if (k <= 0) return 1;
  return Math.round((RTP_PERCENT * binom(CELL_COUNT, k)) / binom(CELL_COUNT - mineCount, k)) / 100;
